import { useEffect, useRef, useState } from "react";
import { lerp, clamp, ease } from "./helpers";
import '../index.css'

const MONTHS = [
  { month: "January",   pct: "2.4%",  highlight: false },
  { month: "February",  pct: "2.81%", highlight: false },
  { month: "March",     pct: "2.94%", highlight: false },
  { month: "April",     pct: "3.17%", highlight: false },
  { month: "May",       pct: "2.81%", highlight: false },
  { month: "June",      pct: "2.75%", highlight: false },
  { month: "July",      pct: "3.2%",  highlight: false },
  { month: "August",    pct: "3.17%", highlight: false },
];

const HighlightMONTHS = [
  { month: "September", pct: "3.36%", highlight: true  },
  { month: "October",   pct: "3.32%", highlight: true  },
  { month: "November",  pct: "3.48%", highlight: true  },
  { month: "December",  pct: "3.4%",  highlight: true  },
];

export default function StatsSection() {
  const [isMobile, setIsMobile] = useState(false);

  useEffect(() => {
    const checkMobile = () => setIsMobile(window.innerWidth < 768);
    checkMobile();
    window.addEventListener("resize", checkMobile);
    return () => window.removeEventListener("resize", checkMobile);
  }, []);

  const [progress, setProgress] = useState(0);
  const sectionRef = useRef(null);

  useEffect(() => {
    const onScroll = () => {
      const el = sectionRef.current; if (!el) return;
      const rect = el.getBoundingClientRect();
      const p = clamp(-rect.top / (el.offsetHeight - window.innerHeight), 0, 1);
      setProgress(p);
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    onScroll();
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  const title1P = 1;
  const hotP    = ease(clamp(progress / 0.12, 0, 1));
  const title2P = ease(clamp((progress - 0.18) / 0.15, 0, 1));
  const subP    = ease(clamp((progress - 0.24) / 0.15, 0, 1));

  const renderCard = (m, i, isHighlight) => {
    const cp = ease(clamp((progress - 0.28 - i * 0.022) / 0.18, 0, 1));
    const imgSrc = isHighlight ? "/assets/highlight-card.png" : "/assets/calender.png";

    return (
      <div
        key={i}
        style={{
          position: "relative",
          opacity: cp,
          transform: `translateY(${lerp(20, 0, cp)}px) scale(${lerp(0.95, 1, cp)})`,
          // Ensure cards never overflow their grid cell
          minWidth: 0,
          width: "100%",
        }}
      >
        <img
          src={imgSrc}
          alt=""
          style={{
            width: "100%",
            display: "block",
            pointerEvents: "none",
            aspectRatio: "248/266",
            // Prevent img from stretching beyond its container
            maxWidth: "100%",
            height: "auto",
          }}
        />

        <div
          style={{
            position: "absolute",
            top: "28%",
            bottom: "6%",
            left: 0,
            right: 0,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            justifyContent: "center",
            gap: "6%",
            pointerEvents: "none",
          }}
        >
          <div style={{
            color: "white",
            // Fluid font — scales with the card's actual rendered width
            fontSize: "clamp(8px, 1.5vw, 22px)",
            fontFamily: "'Inter', sans-serif",
            letterSpacing: 0.3,
            fontWeight: 500,
            textAlign: "center",
          }}>
            {m.month}
          </div>
          <div style={{
            color: "white",
            fontSize: "clamp(11px, 2.6vw, 52px)",
            fontWeight: 700,
            fontFamily: "'Inter', sans-serif",
            lineHeight: 1,
            textAlign: "center",
          }}>
            {m.pct}
          </div>
        </div>
      </div>
    );
  };

  /* ── Mobile hotspot block (unchanged) ── */
  const MobileHotspots = () => (
    <div style={{
      display: "flex",
      flexDirection: "column",
      alignItems: "center",
      width: "100%",
      gap: 0,
      opacity: hotP,
      transform: `translateY(${lerp(20, 0, hotP)}px)`,
    }}>
      <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 6 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <img src="/assets/delivery.png" alt="" style={{ width: 60, height: 60, objectFit: "contain" }} />
          <span style={{ color: "white", fontSize: 22, fontWeight: 600, fontFamily: "Inter", lineHeight: 1.3 }}>
            Delivery<br />Partners
          </span>
        </div>
        <div style={{ color: "#e53e3e", fontSize: 22, fontWeight: 600, fontFamily: "Inter", marginTop: 12 }}>Karnataka</div>
        <div style={{ color: "white", fontSize: "48px", fontWeight: 700, fontFamily: "Inter", lineHeight: 1 }}>6.91%</div>
      </div>

      <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 6, margin: "24px 0" }}>
        <div style={{ width: 0, height: 0, borderLeft: "6px solid transparent", borderRight: "6px solid transparent", borderBottom: "10px solid #CE1010" }} />
        <span style={{ color: "white", fontSize: 17, fontWeight: 700, fontFamily: "Inter", letterSpacing: 0.3 }}>Quick commerce</span>
        <div style={{ width: 0, height: 0, borderLeft: "6px solid transparent", borderRight: "6px solid transparent", borderTop: "10px solid #CE1010" }} />
      </div>

      <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 6 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <img src="/assets/truck_driver.png" alt="" style={{ width: 60, height: 60, objectFit: "contain" }} />
          <span style={{ color: "white", fontSize: 22, fontWeight: 600, fontFamily: "Inter", lineHeight: 1.3 }}>
            Truck<br />Drivers
          </span>
        </div>
        <div style={{ color: "#e53e3e", fontSize: 22, fontWeight: 600, fontFamily: "Inter", marginTop: 12 }}>Maharashtra</div>
        <div style={{ color: "white", fontSize: "48px", fontWeight: 700, fontFamily: "Inter", lineHeight: 1 }}>7.24%</div>
      </div>
    </div>
  );

  return (
    <div ref={sectionRef} style={{ height: "520vh", position: "relative" }}>
      <div
        className="h-auto sm:h-[210vh]"
        style={{
          position: "sticky",
          top: 0,
          // KEY FIX 1: overflow-x hidden so nothing bleeds past the sticky
          // container on Windows (where scrollbar consumes ~17px of width)
          overflow: "hidden",
          background: "black",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          // KEY FIX 2: use box-sizing border-box + percentage/clamp padding
          // so padding never causes overflow regardless of scrollbar width
          boxSizing: "border-box",
          width: "100%",
          padding: isMobile
            ? "48px 16px 36px"
            : "48px clamp(24px, 4vw, 64px) 36px",
        }}
      >

        {/* Title 1 */}
        <h2
          className="sm:text-[105px] text-[30px]"
          style={{
            fontFamily: "'Inter'",
            fontWeight: 700,
            color: "white",
            margin: "30px 0 28px",
            textAlign: "center",
            lineHeight: 1.08,
            // KEY FIX 3: cap maxWidth so it never forces horizontal overflow
            maxWidth: "min(1400px, 100%)",
            opacity: title1P,
            transform: "none",
            fontSize: isMobile ? "30px" : "clamp(60px, 7.5vw, 110px)",
          }}
        >
          E-commerce & Quick<br className="sm:flex hidden" />Commerce Risk Hotspots
        </h2>

        {/* Hotspot Row — desktop only */}
        {!isMobile && (
          <div style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            // KEY FIX 4: width 100% + maxWidth relative so it shrinks on
            // narrower Windows viewports instead of overflowing
            width: "100%",
            maxWidth: "min(1300px, 100%)",
            marginBottom: 44,
            opacity: hotP,
            transform: `translateY(${lerp(20, 0, hotP)}px)`,
          }}>
            {/* Delivery Partners */}
            <div style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "flex-start", gap: 6 }}>
              <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
                <img src="/assets/delivery.png" alt="" style={{ width: 80, height: 80, objectFit: "contain" }} />
                <span style={{ color: "white", fontSize: "clamp(16px, 1.6vw, 24px)", fontWeight: 600, fontFamily: "Inter", lineHeight: 1.3 }}>
                  Delivery<br />Partners
                </span>
              </div>
              <div style={{ color: "#e53e3e", fontSize: "clamp(16px, 1.6vw, 24px)", fontWeight: 600, fontFamily: "Inter", marginTop: 18 }}>Karnataka</div>
              <div style={{ color: "white", fontSize: "clamp(40px, 4.5vw, 65px)", fontWeight: 700, fontFamily: "Inter", lineHeight: 1 }}>6.91%</div>
            </div>

            {/* Center label */}
            <div style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", paddingTop: 6 }}>
              <div style={{ width: 0, height: 0, borderLeft: "8px solid transparent", borderRight: "8px solid transparent", borderBottom: "13px solid #CE1010", marginBottom: 8 }} />
              <span style={{ color: "white", fontSize: "clamp(14px, 1.4vw, 20px)", fontWeight: 700, fontFamily: "Inter", letterSpacing: 0.3 }}>Quick commerce</span>
              <div style={{ width: 0, height: 0, borderLeft: "8px solid transparent", borderRight: "8px solid transparent", borderTop: "13px solid #CE1010", marginTop: 8 }} />
            </div>

            {/* Truck Drivers */}
            <div style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "flex-end", gap: 6 }}>
              <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
                <img src="/assets/truck_driver.png" alt="" style={{ width: 80, height: 80, objectFit: "contain" }} />
                <span style={{ color: "white", fontSize: "clamp(16px, 1.6vw, 24px)", fontWeight: 600, fontFamily: "Inter", lineHeight: 1.3 }}>
                  Truck<br />Drivers
                </span>
              </div>
              <div style={{ color: "#e53e3e", fontSize: "clamp(16px, 1.6vw, 24px)", fontWeight: 600, fontFamily: "Inter", marginTop: 18 }}>Maharashtra</div>
              <div style={{ color: "white", fontSize: "clamp(40px, 4.5vw, 65px)", fontWeight: 700, fontFamily: "Inter", lineHeight: 1 }}>7.24%</div>
            </div>
          </div>
        )}

        {/* Hotspot — mobile only */}
        {isMobile && <MobileHotspots />}

        {/* Title 2 */}
        <h2
          className="pt-16 sm:text-[105px] text-[30px]"
          style={{
            fontFamily: "'Inter','Helvetica Neue',sans-serif",
            fontWeight: 700,
            color: "white",
            margin: "0 0 8px",
            textAlign: "center",
            lineHeight: isMobile ? 1.1 : "115%",
            opacity: title2P,
            transform: `translateY(${lerp(20, 0, title2P)}px)`,
            fontSize: isMobile ? "30px" : "clamp(60px, 8vw, 120px)",
            maxWidth: "min(1400px, 100%)",
          }}
        >
          Seasonal Risk Spikes
        </h2>

        <p style={{
          color: "white",
          margin: "0 0 24px",
          textAlign: "center",
          fontFamily: "Inter",
          opacity: subP,
          fontSize: isMobile ? "11px" : "clamp(16px, 2vw, 30px)",
          lineHeight: isMobile ? 1.3 : "150%",
          maxWidth: "min(900px, 100%)",
        }}>
          A cyclical view of how risk rates spike and decline throughout the year.
        </p>

        {/* Month Grid — always 4 columns */}
        {/* KEY FIX 5: explicit width 100% + box-sizing on the grid itself */}
        <div style={{
          display: "grid",
          gridTemplateColumns: "repeat(4, 1fr)",
          // Fluid gap — shrinks proportionally on narrower viewports
          gap: "clamp(4px, 1.2vw, 24px)",
          width: "100%",
          // KEY FIX 6: replaced min(100%, 1200px) with just 100% so the grid
          // always respects the container's padded width (no overflow on Windows)
          maxWidth: "min(1100px, 100%)",
          boxSizing: "border-box",
          padding: isMobile ? "0 4px" : 0,
        }}>
          {MONTHS.map((m, i) => renderCard(m, i, false))}
          {HighlightMONTHS.map((m, i) => renderCard(m, i + MONTHS.length, true))}
        </div>

        {/* Footer note */}
        <p style={{
          textAlign: "center",
          marginTop: 28,
          fontFamily: "Inter",
          color: "rgba(255,255,255,1)",
          fontWeight: 600,
          opacity: ease(clamp((progress - 0.60) / 0.15, 0, 1)),
          maxWidth: isMobile ? "100%" : "min(1100px, 100%)",
          padding: isMobile ? "0 8px" : 0,
          marginBottom: isMobile ? 0 : 40,
          fontSize: isMobile ? "13px" : "clamp(16px, 2vw, 30px)",
          boxSizing: "border-box",
        }}>
          Risk rates remain consistent throughout the year for all segments,<br className="sm:flex hidden" />
          <span style={{ color: "#CE1010" }}>except for September to December.</span>
        </p>
      </div>
    </div>
  );
}
